arguments.content:
{
 "id": "learning_paradigm",
 "label": "学习范式",
 "gloss": "表示或模型靠什么目标、在什么空间里学"
}

{
 "id": "self_supervised_learning",
 "label": "自监督学习",
 "gloss": "不用人工标签、从数据自身构造预测目标来学表示",
 "aliases": [
  "SSL"
 ]
}

{
 "id": "jepa",
 "label": "联合嵌入预测架构",
 "gloss": "在表示空间里从上下文的表示预测目标的表示,不还原像素",
 "aliases": [
  "JEPA",
  "Joint-Embedding Predictive Architecture"
 ],
 "basis": "LeCun 2022;literature.md §1"
}

{
 "id": "masked_reconstruction",
 "label": "掩码/像素重建",
 "gloss": "在像素或 token 空间重建被遮挡或缺失的输入",
 "aliases": [
  "MAE 式重建",
  "generative SSL"
 ],
 "basis": "literature.md §5"
}

{
 "id": "contrastive_invariance",
 "label": "对比/不变性学习",
 "gloss": "让同一数据的两种增强视图表示一致(含负样本对比或方差-协方差正则)",
 "aliases": [
  "SimCLR/VICReg/DINO 系"
 ],
 "basis": "literature.md §5"
}

{
 "id": "world_model",
 "label": "世界模型",
 "gloss": "给定当前状态(与动作)预测世界下一步会怎样的模型,可用于规划"
}

{
 "id": "latent_world_model",
 "label": "潜空间世界模型",
 "gloss": "只在学到的表示空间里预测未来状态,不生成像素",
 "aliases": [
  "JEPA 世界模型",
  "reconstruction-free world model"
 ],
 "basis": "literature.md §3"
}

{
 "id": "generative_world_model",
 "label": "生成式世界模型",
 "gloss": "在像素/视频 token 空间生成未来观测的世界模型",
 "aliases": [
  "视频生成世界模型"
 ],
 "basis": "literature.md §4"
}

{
 "id": "research_artifact",
 "label": "研究成果",
 "gloss": "一篇论文、一个发布的模型或一个代码库"
}

{
 "id": "model_release",
 "label": "模型/方法",
 "gloss": "提出并发布的具体模型或训练方法"
}

{
 "id": "theory_paper",
 "label": "理论/分析论文",
 "gloss": "以理论或分析为主要贡献的论文(含立场论文)"
}

{
 "id": "software_library",
 "label": "开源库",
 "gloss": "供他人复用的代码库或教程"
}

{
 "id": "experiment_run",
 "label": "实验",
 "gloss": "本工作区内做的可重跑实验"
}

{
 "id": "organization",
 "label": "机构",
 "gloss": "发布研究成果的机构或实验室"
}

{
 "id": "collapse_prevention",
 "label": "防坍缩机制",
 "gloss": "阻止联合嵌入模型把所有输入映射到同一个表示的手段",
 "basis": "literature.md §4 第 3 点"
}

{
 "id": "ema_target_encoder",
 "label": "EMA 目标编码器 + 停梯度",
 "gloss": "目标分支用在线编码器参数的指数滑动平均,且不回传梯度",
 "aliases": [
  "teacher-student",
  "stop-gradient"
 ],
 "basis": "I-JEPA、V-JEPA"
}

{
 "id": "sigreg",
 "label": "SIGReg",
 "gloss": "随机一维投影 + 特征函数检验,把嵌入分布推向各向同性高斯",
 "aliases": [
  "Sketched Isotropic Gaussian Regularization"
 ],
 "basis": "LeJEPA README"
}

{
 "id": "variance_covariance_regularization",
 "label": "方差-协方差正则",
 "gloss": "约束每维方差不低于阈值、各维去相关(VICReg 式)",
 "aliases": [
  "VICReg"
 ],
 "basis": "Sobal 2022 使用"
}

{
 "id": "representation_collapse",
 "label": "表示坍缩",
 "gloss": "编码器输出对所有输入几乎相同,使预测损失平凡地为零"
}

{
 "id": "slow_feature",
 "label": "慢特征",
 "gloss": "随时间几乎不变、因而对预测很'好用'却可能与任务无关的特征(如静态背景)",
 "basis": "Sobal 2022"
}

{
 "id": "latent_planning",
 "label": "潜空间规划",
 "gloss": "在世界模型的表示空间里对候选动作序列打分优化(如 CEM/MPC),以图像目标的表示为目标",
 "basis": "V-JEPA 2-AC、DINO-WM、PLDM"
}

